use rig::extractor::ExtractorBuilder;
use rig::providers::openai::{self, OpenAI};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};


#[derive(Debug, Deserialize, Serialize, JsonSchema)]
struct Person {
    name: Option<String>,
    age: Option<u8>,
    profession: Option<String>,
}


#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let model = OpenAI::from_env()?.completion(openai::GPT_5_5);
    let extractor = ExtractorBuilder::<Person>::new(model).build();


    let person = extractor
        .extract("John Doe is a 30 year old doctor.")
        .await?
        .output;


    println!("{person:?}");
    Ok(())
}

let extractor = ExtractorBuilder::<Person>::new(model)
    .append_preamble("Ages are given in years; ignore honorifics like 'Dr.'")
    .context("Doctors in this dataset are always medical doctors.")
    .max_tokens(512)
    .retries(2)
    .build();

use rig::completion::StructuredOutputError;


match extractor.extract("...").await {
    Ok(response) => { /* use response.output */ }
    Err(StructuredOutputError::EmptyResponse) => {
        eprintln!("the model did not produce structured data");
    }
    Err(StructuredOutputError::Deserialization { output, error }) => {
        eprintln!("unparseable output ({error}): {output}");
    }
    Err(err) => return Err(err.into()),
}

use futures::{StreamExt, TryStreamExt};
use rig::loaders::FileLoader;


let docs: Vec<String> = FileLoader::with_glob("notes/*.txt")?
    .read()
    .ignore_errors()
    .into_iter()
    .collect();


let people: Vec<Person> = futures::stream::iter(&docs)
    .map(|doc| async { extractor.extract(doc.as_str()).await.map(|r| r.output) })
    .buffered(4)
    .try_collect()
    .await?;
